  `UPDATE_USER` varchar(20) DEFAULT NULL COMMENT '修改用户',
  `SORT_CODE` int(11) DEFAULT 0 COMMENT '排序码',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `idx_proj_leader` (`LEADER_ID`) USING BTREE,
  KEY `idx_proj_privacy` (`IS_PRIVATE`) USING BTREE,
