--
-- Table structure for table `dev_dict`
--

DROP TABLE IF EXISTS `dev_dict`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dev_dict` (
  `ID` varchar(20) NOT NULL COMMENT '主键',
  `PARENT_ID` varchar(20) DEFAULT NULL COMMENT '父id',
  `DICT_LABEL` varchar(255) DEFAULT NULL COMMENT '字典文字',
  `DICT_VALUE` varchar(255) DEFAULT NULL COMMENT '字典值',
  `DICT_COLOR` varchar(255) DEFAULT NULL COMMENT '字典颜色',
  `CODE` varchar(255) DEFAULT NULL COMMENT '编码',
  `CATEGORY` varchar(255) DEFAULT NULL COMMENT '分类',
  `SORT_CODE` int(11) DEFAULT NULL COMMENT '排序码',
  `EXT_JSON` longtext DEFAULT NULL COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='字典';
/*!40101 SET character_set_client = @saved_cs_client */;

