r\\n\\t\\treturn request(\'exportData\', data, \'post\', {\\r\\n\\t\\t\\tresponseType: \'blob\'\\r\\n\\t\\t})\\r\\n\\t},\\r\\n}\\r\\n\"},{\"codeFileName\":\"form.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\competition\\\\form.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container\\r\\n\\t\\t:title=\\\"formData.id ? \'编辑竞赛信息管理\' : \'增加竞赛信息管理\'\\\"\\r\\n\\t\\t:width=\\\"700\\\"\\r\\n\\t\\tv-model:open=\\\"open\\\"\\r\\n\\t\\t:destroy-on-close=\\\"true\\\"\\r\\n\\t\\t@close=\\\"onClose\\\"\\r\\n\\t>\\r\\n\\t\\t<a-form ref=\\\"formRef\\\" :model=\\\"formData\\\" :rules=\\\"formRules\\\" layout=\\\"vertical\\\">\\r\\n\\t\\t\\t<a-row :gutter=\\\"16\\\">\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"竞赛名称：\\\" name=\\\"title\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.title\\\" placeholder=\\\"请输入竞赛名称\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"竞赛级别：SCHOOL-校级, PROVINCE-省级, NATIONAL-国家级, INTERNATIONAL-国际级：\\\" name=\\\"competitionLevel\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.competitionLevel\\\" placeholder=\\\"请输入竞赛级别：SCHOOL-校级, PROVINCE-省级, NATIONAL-国家级, INTERNATIONAL-国际级\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"主办单位/承办方：\\\" name=\\\"organizer\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.organizer\\\" placeholder=\\\"请输入主办单位/承办方\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\