rt.show\\\"\\r\\n\\t\\t\\tbordered\\r\\n\\t\\t\\t:row-key=\\\"(record) => record.id\\\"\\r\\n\\t\\t\\t:tool-config=\\\"toolConfig\\\"\\r\\n\\t\\t\\t:row-selection=\\\"options.rowSelection\\\"\\r\\n\\t\\t\\t:scroll=\\\"{ x: \'max-content\' }\\\"\\r\\n\\t\\t>\\r\\n\\t\\t\\t<template #operator>\\r\\n\\t\\t\\t\\t<a-space>\\r\\n\\t\\t\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"formRef.onOpen()\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectAdd\')\\\">\\r\\n\\t\\t\\t\\t\\t\\t<template #icon><plus-outlined /></template>\\r\\n\\t\\t\\t\\t\\t\\t新增\\r\\n\\t\\t\\t\\t\\t</a-button>\\r\\n\\t\\t\\t\\t\\t<a-button @click=\\\"importModelRef.onOpen()\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectImport\')\\\">\\r\\n                        <template #icon><import-outlined /></template>\\r\\n                        <span>导入</span>\\r\\n                    </a-button>\\r\\n                    <a-button @click=\\\"exportData\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectExport\')\\\">\\r\\n                        <template #icon><export-outlined /></template>\\r\\n                        <span>导出</span>\\r\\n                    </a-button>\\r\\n\\t\\t\\t\\t\\t<xn-batch-button\\r\\n\\t\\t\\t\\t\\t\\tv-if=\\\"hasPerm(\'bizCompetitionProjectBatchDelete\')\\\"\\r\\n\\t\\t\\t\\t\\t\\tbuttonName=\\\"批量删除\\\"\\r\\n\\t\\t\\t\\t\\t\\ticon=\\\"DeleteOutlined\\\"\\r\\n\\t\\t\\t\\t\\t\\tbuttonDanger\\r\\n\\t\\t\\t\\t\\t\\t:id-key=\\\"\'id\'\\\"\\r\\n\\t\\t\\t\\t\\t\\t:selectedRowKeys=\\\"selectedRowKeys\\\"\\r\\n\\t\\t\\t\\t\\t\\t@batchCallBack=\\\"deleteBatchBizCompetitionProject\\\"\\r\\n\\t\\t\\t\\t\\t/>\\r\\n\\t\\t\\t\\t</a-space>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t\\t<template #bodyCell=\\\"{ column, record }\\\">\\r\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'action\'\\\">\\r\\n\\t\\t\\t\\t\\t<a-space>\\r\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"detailRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectDetail\')\\\">详情</a>\\r\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'bizCompetitionProjectDetail\', \'bizCompetitionProjectEdit\'], \'and\')\\\" />\\r\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"formRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectEdit\')\\\">编辑</a>\\r\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'bizCompetitionProjectEdit\', \'bizCompetitionProjectDelete\'], \'and\')\\\" />\\r\\n\\t\\t\\t\\t\\t\\t<a-popconfirm title=\\\"确定要删除吗？\\\" @confirm=\\\"deleteBizCompetitionProject(record)\\\">\\r\\n\\t\\t\\t\\t\\t\\t\\t<a-button type=\\\"link\\\" danger size=\\\"small\\\" v-if=\\\"hasPerm(\'bizCompetitionProjectDelete\')\\\">删除</a-button>\\r\\n\\t\\t\\t\\t\\t\\t</a-popconfirm>\\r\\n\\t\\t\\t\\t\\t</a-space>\\r\\n\\t\\t\\t\\t</template>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t</s-table>\\r\\n\\t</xn-panel>\\r\\n\\t<ImportModel ref=\\\"importModelRef\\\" />\\r\\n\\t<Form ref=\\\"formRef\\\" @successful=\\\"tableRef.refresh()\\\" />\\r\\n\\t<Detail ref=\\\"detailRef\\\" />\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"competitionproject\\\">\\r\\n\\timport { cloneDeep } from \'lodash-es\'\\r\\n\\timport Form from \'./form.vue\'\\r\\n\\timport Detail from \'./detail.vue\'\\r\\n\\timport ImportModel from \'./importModel.vue\'\\r\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\r\\n\\timport bizCompetitionProjectApi from \'@/api/biz/bizCompetitionProjectApi\'\\r\\n\\tconst tableRef = ref()\\r\\n\\tconst importModelRef = ref()\\r\\n\\tconst formRef = ref()\\r\\n\\tconst detailRef = ref()\\r\\n\\tconst toolConfig = { refresh: true, height: true, columnSetting: true, striped: false }\\r\\n\\tconst columns = [\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'竞赛ID（关联BIZ_COMPETITION.ID）\',\\r\\n\\t\\t\\tdataIndex: \'competitionId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'参赛形式：PROJECT-团队参赛, INDIVIDUAL-个人参赛\',\\r\\n\\t\\t\\tdataIndex: \'signupType\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'参赛项目组ID（多对多关联BIZ_PROJECT.ID，团队参赛时必填，仅组长可操作）\',\\r\\n\\t\\t\\tdataIndex: \'projectId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'参赛学生ID（个人参赛时必填，关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'studentId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'指导老师用户ID（关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'instructorTeacherId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'报名时间\',\\r\\n\\t\\t\\tdataIndex: \'enrollTime\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'参赛资格审核状态：PENDING-待审核, PASSED-报名成功, REJECTED-已驳回\',\\r\\n\\t\\t\\tdataIndex: \'auditStatus\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'最终赛果/名次（如一等奖/银奖/进入决赛等）\',\\r\\n\\t\\t\\tdataIndex: \'competitionResult\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'扩展报名资料(JSON)\',\\r\\n\\t\\t\\tdataIndex: \'extJson\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'排序码\',\\r\\n\\t\\t\\tdataIndex: \'sortCode\'\\r\\n\\t\\t},\\r\\n\\t]\\r\\n\\t// 操作栏通过权限判断是否显示\\r\\n\\tif (hasPerm([\'bizCompetitionProjectEdit\', \'bizCompetitionProjectDelete\', \'bizCompetitionProjectDetail\'])) {\\r\\n\\t\\tcolumns.push({\\r\\n\\t\\t\\ttitle: \'操作\',\\r\\n\\t\\t\\tdataIndex: \'action\',\\r\\n\\t\\t\\talign: \'center\',\\r\\n\\t\\t\\tfixed: \'right\'\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\tconst selectedRowKeys = ref([])\\r\\n\\t// 列表选择配置\\r\\n\\tconst options = {\\r\\n\\t\\talert: {\\r\\n\\t\\t\\tshow: true,\\r\\n\\t\\t\\tclear: () => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\r\\n\\t\\t\\t}\\r\\n\\t\\t},\\r\\n\\t\\trowSelection: {\\r\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\r\\n\\t\\t\\t}\\r\\n\\t\\t}\\r\\n\\t}\\r\\n\\tconst loadData = (parameter) => {\\r\\n\\t\\treturn bizCompetitionProjectApi.bizCompetitionProjectPage(parameter).then((data) => {\\r\\n\\t\\t\\treturn data\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 重置\\r\\n\\tconst reset = () => {\\r\\n\\t\\tsearchFormRef.value.resetFields()\\r\\n\\t\\ttableRef.value.refresh(true)\\r\\n\\t}\\r\\n\\t// 删除\\r\\n\\tconst deleteBizCompetitionProject = (record) => {\\r\\n\\t\\tlet params = [\\r\\n\\t\\t\\t{\\r\\n\\t\\t\\t\\tid: record.id\\r\\n\\t\\t\\t}\\r\\n\\t\\t]\\r\\n\\t\\tbizCompetitionProjectApi.bizCompetitionProjectDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.refresh(true)\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 导出\\r\\n    const exportData = () => {\\r\\n        if (selectedRowKeys.value.length > 0) {\\r\\n            const params = selectedRowKeys.value.map((m) => {\\r\\n                return {\\r\\n                    id: m\\r\\n                }\\r\\n            })\\r\\n            bizCompetitionProjectApi.bizCompetitionProjectExport(params).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        } else {\\r\\n            bizCompetitionProjectApi.bizCompetitionProjectExport([]).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        }\\r\\n    }\\r\\n\\t// 批量删除\\r\\n\\tconst deleteBatchBizCompetitionProject = (params) => {\\r\\n\\t\\tbizCompetitionProjectApi.bizCompetitionProjectDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\r\\n\\t\\t})\\r\\n\\t}\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\competitionproject\\\\importModel.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\r\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\r\\n\\t\\t</span>\\r\\n\\t\\t<a-divider dashed />\\r\\n\\t\\t<div>\\r\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\r\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\r\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\r\\n\\t\\t\\t\\t\\t</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-text\\\">单击或拖动文件到此区域进行上传</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-hint\\\">仅支持xls、xlsx格式文件</p>\\r\\n\\t\\t\\t\\t</a-upload-dragger>\\r\\n\\t\\t\\t</a-spin>\\r\\n\\t\\t</div>\\r\\n\\t\\t<a-alert v-if=\\\"impAlertStatus\\\" type=\\\"info\\\" :show-icon=\\\"false\\\" banner closable @close=\\\"onImpClose\\\" class=\\\"mt-3\\\">\\r\\n\\t\\t\\t<template #description>\\r\\n\\t\\t\\t\\t<p>导入总数：{{ impResultData.totalCount }} 条</p>\\r\\n\\t\\t\\t\\t<p>导入成功：{{ impResultData.successCount }} 条</p>\\r\\n\\t\\t\\t\\t<div v-if=\\\"impResultData.errorCount > 0\\\">\\r\\n\\t\\t\\t\\t\\t<p><span class=\\\"xn-color-red\\\">失败条数：</span>{{ impResultData.errorCount }} 条</p>\\r\\n\\t\\t\\t\\t\\t<a-table :dataSource=\\\"impResultErrorDataSource\\\" :columns=\\\"impErrorColumns\\\" size=\\\"small\\\" />\\r\\n\\t\\t\\t\\t</div>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t</a-alert>\\r\\n\\t</xn-form-container>\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"bizCompetitionProjectImportModel\\\">\\r\\n\\timport { message } from \'ant-design-vue\'\\r\\n\\timport bizCompetitionProjectApi from \'@/api/biz/bizCompetitionProjectApi\'\\r\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\r\\n\\r\\n\\tconst impUploadLoading = ref(false)\\r\\n\\tconst impAlertStatus = ref(false)\\r\\n\\tconst impResultData = ref({})\\r\\n\\tconst impResultErrorDataSource = ref([])\\r\\n\\tconst impAccept = [\\r\\n\\t\\t{\\r\\n\\t\\t\\textension: \'.xls\',\\r\\n\\t\\t\\tmimeType: \'application/vnd.ms-excel\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\textension: \'.xlsx\',\\r\\n\\t\\t\\tmimeType: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\'\\r\\n\\t\\t}\\r\\n\\t]\\r\\n\\t// 指定能选择的文件类型\\r\\n\\tconst uploadAccept = String(\\r\\n\\t\\timpAccept.map((item) => {\\r\\n\\t\\t\\treturn item.mimeType\\r\\n\\t\\t})\\r\\n\\t)\\r\\n\\t// 导入\\r\\n\\tconst customRequestLocal = (data) => {\\r\\n\\t\\timpUploadLoading.value = true\\r\\n\\t\\tconst fileData = new FormData()\\r\\n\\t\\t// 校验上传文件扩展名和文件类型是否为.xls、.xlsx\\r\\n\\t\\tconst extension = \'.\'.concat(data.file.name.split(\'.\').slice(-1).toString().toLowerCase())\\r\\n\\t\\tconst mimeType = data.file.type\\r\\n\\t\\t// 提取允许的扩展名\\r\\n\\t\\tconst extensionArr = impAccept.map((item) => item.extension)\\r\\n\\t\\t// 提取允许的MIMEType\\r\\n\\t\\tconst mimeTypeArr = impAccept.map((item) => item.mimeType)\\r\\n\\t\\tif (!extensionArr.includes(extension) || !mimeTypeArr.includes(mimeType)) {\\r\\n\\t\\t\\tmessage.warning(\'上传文件类型仅支持xls、xlsx格式文件！\')\\r\\n\\t\\t\\timpUploadLoading.value = false\\r\\n\\t\\t\\treturn false\\r\\n\\t\\t}\\r\\n\\t\\tfileData.append(\'file\', data.file)\\r\\n\\t\\treturn bizCompetitionProjectApi\\r\\n\\t\\t\\t.bizCompetitionProjectImport(fileData)\\r\\n\\t\\t\\t.then((res) => {\\r\\n\\t\\t\\t\\timpAlertStatus.value = true\\r\\n\\t\\t\\t\\timpResultData.value = res\\r\\n\\t\\t\\t\\timpResultErrorDataSource.value = res.errorDetail\\r\\n\\t\\t\\t})\\r\\n\\t\\t\\t.finally(() => {\\r\\n\\t\\t\\t\\timpUploadLoading.value = false\\r\\n\\t\\t\\t})\\r\\n\\t}\\r\\n\\t// 关闭导入提示\\r\\n\\tconst onImpClose = () => {\\r\\n\\t\\timpAlertStatus.value = false\\r\\n\\t}\\r\\n\\tconst impErrorColumns = [\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'索引\',\\r\\n\\t\\t\\tdataIndex: \'index\',\\r\\n\\t\\t\\twidth: \'80px\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'原因\',\\r\\n\\t\\t\\tdataIndex: \'msg\'\\r\\n\\t\\t}\\r\\n\\t]\\r\\n\\t// 定义emit事件\\r\\n\\tconst emit = defineEmits({ successful: null })\\r\\n\\t// 默认是关闭状态\\r\\n\\tconst visible = ref(false)\\r\\n\\tconst submitLoading = ref(false)\\r\\n\\r\\n\\t// 打开抽屉\\r\\n\\tconst onOpen = () => {\\r\\n\\t\\tvisible.value = true\\r\\n\\t}\\r\\n\\t// 关闭抽屉\\r\\n\\tconst onClose = () => {\\r\\n\\t\\tvisible.value = false\\r\\n\\t\\t// 关闭导入的提示\\r\\n\\t\\tonImpClose()\\r\\n\\t}\\r\\n\\t// 下载导入模板\\r\\n\\tconst downloadImportTemplate = () => {\\r\\n\\t\\tbizCompetitionProjectApi.bizCompetitionProjectDownloadTemplate().then((re