il\'\\r\\n\\timport bizCompetitionCertApi from \'@/api/biz/bizCompetitionCertApi\'\\r\\n\\tconst tableRef = ref()\\r\\n\\tconst importModelRef = ref()\\r\\n\\tconst formRef = ref()\\r\\n\\tconst detailRef = ref()\\r\\n\\tconst toolConfig = { refresh: true, height: true, columnSetting: true, striped: false }\\r\\n\\tconst columns = [\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'所属竞赛ID（关联BIZ_COMPETITION.ID）\',\\r\\n\\t\\t\\tdataIndex: \'competitionId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'所属项目ID（关联BIZ_PROJECT.ID）\',\\r\\n\\t\\t\\tdataIndex: \'projectId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'获得证书学生ID（关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'studentId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'证书名称\',\\r\\n\\t\\t\\tdataIndex: \'certificateName\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'获奖级别（国家一等奖/省级二等奖/优秀奖等）\',\\r\\n\\t\\t\\tdataIndex: \'awardLevel\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'获奖日期\',\\r\\n\\t\\t\\tdataIndex: \'awardDate\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'证书扫描件/照片文件ID（关联DEV_FILE.ID）\',\\r\\n\\t\\t\\tdataIndex: \'fileId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'上传人用户ID（组员或组长皆可上传）\',\\r\\n\\t\\t\\tdataIndex: \'uploadUserId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'教师认证状态：PENDING-待认证, VERIFIED-已认证, REJECTED-已驳回\',\\r\\n\\t\\t\\tdataIndex: \'verifyStatus\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'认证教师ID（关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'verifyTeacherId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'审核评语\',\\r\\n\\t\\t\\tdataIndex: \'verifyRemark\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'排序码\',\\r\\n\\t\\t\\tdataIndex: \'sortCode\'\\r\\n\\t\\t},\\r\\n\\t]\\r\\n\\t// 操作栏通过权限判断是否显示\\r\\n\\tif (hasPerm([\'bizCompetitionCertEdit\', \'bizCompetitionCertDelete\', \'bizCompetitionCertDetail\'])) {\\r\\n\\t\\tcolumns.push({\\r\\n\\t\\t\\ttitle: \'操作\',\\r\\n\\t\\t\\tdataIndex: \'action\',\\r\\n\\t\\t\\talign: \'center\',\\r\\n\\t\\t\\tfixed: \'right\'\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\tconst selectedRowKeys = ref([])\\r\\n\\t// 列表选择配置\\r\\n\\tconst options = {\\r\\n\\t\\talert: {\\r\\n\\t\\t\\tshow: true,\\r\\n\\t\\t\\tclear: () => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\r\\n\\t\\t\\t}\\r\\n\\t\\t},\\r\\n\\t\\trowSelection: {\\r\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\r\\n\\t\\t\\t}\\r\\n\\t\\t}\\r\\n\\t}\\r\\n\\tconst loadData = (parameter) => {\\r\\n\\t\\treturn bizCompetitionCertApi.bizCompetitionCertPage(parameter).then((data) => {\\r\\n\\t\\t\\treturn data\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 重置\\r\\n\\tconst reset = () => {\\r\\n\\t\\tsearchFormRef.value.resetFields()\\r\\n\\t\\ttableRef.value.refresh(true)\\r\\n\\t}\\r\\n\\t// 删除\\r\\n\\tconst deleteBizCompetitionCert = (record) => {\\r\\n\\t\\tlet params = [\\r\\n\\t\\t\\t{\\r\\n\\t\\t\\t\\tid: record.id\\r\\n\\t\\t\\t}\\r\\n\\t\\t]\\r\\n\\t\\tbizCompetitionCertApi.bizCompetitionCertDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.refresh(true)\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 导出\\r\\n    const exportData = () => {\\r\\n        if (selectedRowKeys.value.length > 0) {\\r\\n            const params = selectedRowKeys.value.map((m) => {\\r\\n                return {\\r\\n                    id: m\\r\\n                }\\r\\n            })\\r\\n            bizCompetitionCertApi.bizCompetitionCertExport(params).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        } else {\\r\\n            bizCompetitionCertApi.bizCompetitionCertExport([]).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        }\\r\\n    }\\r\\n\\t// 批量删除\\r\\n\\tconst deleteBatchBizCompetitionCert = (params) => {\\r\\n\\t\\tbizCompetitionCertApi.bizCompetitionCertDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\r\\n\\t\\t})\\r\\n\\t}\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\competitioncert\\\\importModel.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\r\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\r\\n\\t\\t</span>\\r\\n\\t\\t<a-divider dashed />\\r\\n\\t\\t<div>\\r\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\r\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\r\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\r\\n\\t\\t\\t\\t\\t</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-text\\\">单击或拖动文件到此区域进行上传</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-hint\\\">仅支持xls、xlsx格式文件</p>\\r\\n\\t\\t\\t\\t</a-upload-dragger>\\r\\n\\t\\t\\t</a-spin>\\r\\n\\t\\t</div>\\r\\n\\t\\t<a-alert v-if=\\\"impAlertStatus\\\" type=\\\"info\\\" :show-icon=\\\"false\\\" banner closable @close=\\\"onImpClose\\\" class=\\\"mt-3\\\">\\r\\n\\t\\t\\t<template #description>\\r\\n\\t\\t\\t\\t<p>导入总数：{{ impResultData.totalCount }} 条</p>\\r\\n\\t\\t\\t\\t<p>导入成功：{{ impResultData.successCount }} 条</p>\\r\\n\\t\\t\\t\\t<div v-if=\\\"impResultData.errorCount > 0\\\">\\r\\n\\t\\t\\t\\t\\t<p><span class=\\\"xn-color-red\\\">失败条数：</span>{{ impResultData.errorCount }} 条</p>\\r\\n\\t\\t\\t\\t\\t<a-table :dataSource=\\\"impResultErrorDataSource\\\" :columns=\\\"impErrorColumns\\\" size=\\\"small\\\" />\\r\\n\\t\\t\\t\\t</div>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t</a-alert>\\r\\n\\t</xn-form-container>\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"bizCompetitionCertImportModel\\\">\\r\\n\\timport { message } from \'ant-design-vue\'\\r\\n\\timport bizCompetitionCertApi from \'@/api/biz/bizCompetitionCertApi\'\\r\\n\\t