 onClose = () => {\\r\\n\\t\\tformData.value = {}\\r\\n\\t\\topen.value = false\\r\\n\\t}\\r\\n\\t// 下载文件\\r\\n\\tconst downloadFile = (url) => {\\r\\n\\t\\twindow.open(url)\\r\\n\\t}\\r\\n\\t// 抛出函数\\r\\n\\tdefineExpose({\\r\\n\\t\\tonOpen\\r\\n\\t})\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"index.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\algorithmurge\\\\index.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-panel>\\r\\n\\t\\t<s-table\\r\\n\\t\\t\\tref=\\\"tableRef\\\"\\r\\n\\t\\t\\t:columns=\\\"columns\\\"\\r\\n\\t\\t\\t:data=\\\"loadData\\\"\\r\\n\\t\\t\\t:alert=\\\"options.alert.show\\\"\\r\\n\\t\\t\\tbordered\\r\\n\\t\\t\\t:row-key=\\\"(record) => record.id\\\"\\r\\n\\t\\t\\t:tool-config=\\\"toolConfig\\\"\\r\\n\\t\\t\\t:row-selection=\\\"options.rowSelection\\\"\\r\\n\\t\\t\\t:scroll=\\\"{ x: \'max-content\' }\\\"\\r\\n\\t\\t>\\r\\n\\t\\t\\t<template #operator>\\r\\n\\t\\t\\t\\t<a-space>\\r\\n\\t\\t\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"formRef.onOpen()\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeAdd\')\\\">\\r\\n\\t\\t\\t\\t\\t\\t<template #icon><plus-outlined /></template>\\r\\n\\t\\t\\t\\t\\t\\t新增\\r\\n\\t\\t\\t\\t\\t</a-button>\\r\\n\\t\\t\\t\\t\\t<a-button @click=\\\"importModelRef.onOpen()\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeImport\')\\\">\\r\\n                        <template #icon><import-outlined /></template>\\r\\n                        <span>导入</span>\\r\\n                    </a-button>\\r\\n                    <a-button @click=\\\"exportData\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeExport\')\\\">\\r\\n                        <template #icon><export-outlined /></template>\\r\\n                        <span>导出</span>\\r\\n                    </a-button>\\r\\n\\t\\t\\t\\t\\t<xn-batch-button\\r\\n\\t\\t\\t\\t\\t\\tv-if=\\\"hasPerm(\'bizAlgorithmUrgeBatchDelete\')\\\"\\r\\n\\t\\t\\t\\t\\t\\tbuttonName=\\\"批量删除\\\"\\r\\n\\t\\t\\t\\t\\t\\ticon=\\\"DeleteOutlined\\\"\\r\\n\\t\\t\\t\\t\\t\\tbuttonDanger\\r\\n\\t\\t\\t\\t\\t\\t:id-key=\\\"\'id\'\\\"\\r\\n\\t\\t\\t\\t\\t\\t:selectedRowKeys=\\\"selectedRowKeys\\\"\\r\\n\\t\\t\\t\\t\\t\\t@batchCallBack=\\\"deleteBatchBizAlgorithmUrge\\\"\\r\\n\\t\\t\\t\\t\\t/>\\r\\n\\t\\t\\t\\t</a-space>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t\\t<template #bodyCell=\\\"{ column, record }\\\">\\r\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'action\'\\\">\\r\\n\\t\\t\\t\\t\\t<a-space>\\r\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"detailRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeDetail\')\\\">详情</a>\\r\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'bizAlgorithmUrgeDetail\', \'bizAlgorithmUrgeEdit\'], \'and\')\\\" />\\r\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"formRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeEdit\')\\\">编辑</a>\\r\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'bizAlgorithmUrgeEdit\', \'bizAlgorithmUrgeDelete\'], \'and\')\\\" />\\r\\n\\t\\t\\t\\t\\t\\t<a-popconfirm title=\\\"确定要删除吗？\\\" @confirm=\\\"deleteBizAlgorithmUrge(record)\\\">\\r\\n\\t\\t\\t\\t\\t\\t\\t<a-button type=\\\"link\\\" danger size=\\\"small\\\" v-if=\\\"hasPerm(\'bizAlgorithmUrgeDelete\')\\\">删除</a-button>\\r\\n\\t\\t\\t\\t\\t\\t</a-popconfirm>\\r\\n\\t\\t\\t\\t\\t</a-space>\\r\\n\\t\\t\\t\\t</template>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t</s-table>\\r\\n\\t</xn-panel>\\r\\n\\t<ImportModel ref=\\\"importModelRef\\\" />\\r\\n\\t<Form ref=\\\"formRef\\\" @successful=\\\"tableRef.refresh()\\\" />\\r\\n\\t<Detail ref=\\\"detailRef\\\" />\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"algorithmurge\\\">\\r\\n\\timport { cloneDeep } from \'lodash-es\'\\r\\n\\timport Form from \'./form.vue\'\\r\\n\\timport Detail from \'./detail.vue\'\\r\\n\\timport ImportModel from \'./importModel.vue\'\\r\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\r\\n\\timport bizAlgorithmUrgeApi from \'@/api/biz/bizAlgorithmUrgeApi\'\\r\\n\\tconst tableRef = ref()\\r\\n\\tconst importModelRef = ref()\\r\\n\\tconst formRef = ref()\\r\\n\\tconst detailRef = ref()\\r\\n\\tconst toolConfig = { refresh: true, height: true, columnSetting: true, striped: false }\\r\\n\\tconst columns = [\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'催交的算法任务ID（关联BIZ_ALGORITHM_TASK.ID）\',\\r\\n\\t\\t\\tdataIndex: \'taskId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'所在项目组ID（关联BIZ_PROJECT.ID）\',\\r\\n\\t\\t\\tdataIndex: \'projectId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'催促组长用户ID（关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'leaderId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'被催促的组员学生ID（关联SYS_USER.ID）\',\\r\\n\\t\\t\\tdataIndex: \'studentId\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'催促消息内容\',\\r\\n\\t\\t\\tdataIndex: \'urgeMessage\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'催促时间\',\\r\\n\\t\\t\\tdataIndex: \'urgeTime\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'排序码\',\\r\\n\\t\\t\\tdataIndex: \'sortCode\'\\r\\n\\t\\t},\\r\\n\\t]\\r\\n\\t// 操作栏通过权限判断是否显示\\r\\n\\tif (hasPerm([\'bizAlgorithmUrgeEdit\', \'bizAlgorithmUrgeDelete\', \'bizAlgorithmUrgeDetail\'])) {\\r\\n\\t\\tcolumns.push({\\r\\n\\t\\t\\ttitle: \'操作\',\\r\\n\\t\\t\\tdataIndex: \'action\',\\r\\n\\t\\t\\talign: \'center\',\\r\\n\\t\\t\\tfixed: \'right\'\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\tconst selectedRowKeys = ref([])\\r\\n\\t// 列表选择配置\\r\\n\\tconst options = {\\r\\n\\t\\talert: {\\r\\n\\t\\t\\tshow: true,\\r\\n\\t\\t\\tclear: () => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\r\\n\\t\\t\\t}\\r\\n\\t\\t},\\r\\n\\t\\trowSelection: {\\r\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\r\\n\\t\\t\\t}\\r\\n\\t\\t}\\r\\n\\t}\\r\\n\\tconst loadData = (parameter) => {\\r\\n\\t\\treturn bizAlgorithmUrgeApi.bizAlgorithmUrgePage(parameter).then((data) => {\\r\\n\\t\\t\\treturn data\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 重置\\r\\n\\tconst reset = () => {\\r\\n\\t\\tsearchFormRef.value.resetFields()\\r\\n\\t\\ttableRef.value.refresh(true)\\r\\n\\t}\\r\\n\\t// 删除\\r\\n\\tconst deleteBizAlgorithmUrge = (record) => {\\r\\n\\t\\tlet params = [\\r\\n\\t\\t\\t{\\r\\n\\t\\t\\t\\tid: record.id\\r\\n\\t\\t\\t}\\r\\n\\t\\t]\\r\\n\\t\\tbizAlgorithmUrgeApi.bizAlgorithmUrgeDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.refresh(true)\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 导出\\r\\n    const exportData = () => {\\r\\n        if (selectedRowKeys.value.length > 0) {\\r\\n            const params = selectedRowKeys.value.map((m) => {\\r\\n                return {\\r\\n                    id: m\\r\\n                }\\r\\n            })\\r\\n            bizAlgorithmUrgeApi.bizAlgorithmUrgeExport(params).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        } else {\\r\\n            bizAlgorithmUrgeApi.bizAlgorithmUrgeExport([]).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        }\\r\\n    }\\r\\n\\t// 批量删除\\r\\n\\tconst deleteBatchBizAlgorithmUrge = (params) => {\\r\\n\\t\\tbizAlgorithmUrgeApi.bizAlgorithmUrgeDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\r\\n\\t\\t})\\r\\n\\t}\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\algorithmurge\\\\importModel.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\r\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\r\\n\\t\\t</span>\\r\\n\\t\\t<a-divider dashed />\\r\\n\\t\\t<div>\\r\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\r\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\r\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\