CompetitionProjectServiceImpl extends ServiceImpl<BizCompetitionProjectMapper, BizCompetitionProject> implements BizCompetitionProjectService {\\r\\n\\r\\n    @Override\\r\\n    public Page<BizCompetitionProject> page(BizCompetitionProjectPageParam bizCompetitionProjectPageParam) {\\r\\n        QueryWrapper<BizCompetitionProject> queryWrapper = new QueryWrapper<BizCompetitionProject>().checkSqlInjection();\\r\\n        if(ObjectUtil.isAllNotEmpty(bizCompetitionProjectPageParam.getSortField(), bizCompetitionProjectPageParam.getSortOrder())) {\\r\\n            CommonSortOrderEnum.validate(bizCompetitionProjectPageParam.getSortOrder());\\r\\n            queryWrapper.orderBy(true, bizCompetitionProjectPageParam.getSortOrder().equals(CommonSortOrderEnum.ASC.getValue()),\\r\\n                    StrUtil.toUnderlineCase(bizCompetitionProjectPageParam.getSortField()));\\r\\n        } else {\\r\\n            queryWrapper.lambda().orderByAsc(BizCompetitionProject::getSortCode);\\r\\n        }\\r\\n        // 校验数据范围\\r\\n        List<String> loginUserDataScope = StpLoginUserUtil.getLoginUserDataScope();\\r\\n        if(loginUserDataScope != null && loginUserDataScope.isEmpty()) {\\r\\n            return new Page<>();\\r\\n        }\\r\\n        if(ObjectUtil.isNotEmpty(loginUserDataScope)) {\\r\\n            // 根据业务需要，取消下面注释并修改为实际的数据范围字段，例如：orgId\\r\\n            // CommonSqlUtil.scopeIn(queryWrapper.lambda(), BizCompetitionProject::getOrgId, StpUtil.getLoginIdAsString(), CommonServletUtil.getRequest().getServletPath());\\r\\n        }\\r\\n        return this.page(CommonPageRequest.defaultPage(), queryWrapper);\\r\\n    }\\r\\n\\r\\n    @Transactional(rollbackFor = Exception.class)\\r\\n    @Override\\r\\n    public void add(BizCompetitionProjectAddParam bizCompetitionProjectAddParam) {\\r\\n        BizCompetitionProject bizCompetitionProject = BeanUtil.toBean(bizCompetitionProjectAddParam, BizCompetitionProject.class);\\r\\n        // 校验数据范围\\r\\n        List<String> loginUserDataScope = StpLoginUserUtil.getLoginUserDataScope();\\r\\n        if(loginUserDataScope != null && loginUserDataScope.isEmpty()) {\\r\\n            throw new CommonException(\\\"您没有权限增加竞赛报名关联\\\");\\r\\n        }\\r\\n        if(ObjectUtil.isNotEmpty(loginUserDataScope)) {\\r\\n            // 根据业务需要，取消下面注释并修改为实际的数据范围字段，例如：orgId\\r\\n            // if(!loginUserDataScope.contains(bizCompetitionProject.getOrgId())) {\\r\\n            //     throw new CommonException(\\\"您没有权限在该机构下增加竞赛报名关联\\\");\\r\\n            // }\\r\\n        }\\r\\n\\r\\n        this.save(bizCompetitionProject);\\r\\n    }\\r\\n\\r\\n    @Transactional(rollbackFor = Exception.class)\\r\\n    @Override\\r\\n    public void edit(BizCompetitionProjectEditParam bizCompetitionProjectEditParam) {\\r\\n        BizCompetitionProject bizCompetitionProject = this.queryEntity(bizCompetitionProjectEditParam.getId());\\r\\n        BeanUtil.copyProperties(bizCompetitionProjectEditParam, bizCompetitionProject);\\r\\n        // 校验数据范围\\r\\n        List<String> loginUserDataScope = StpLoginUserUtil.getLoginUserDataScope();\\r\\n        if(loginUserDataScope != null && loginUserDataScope.isEmpty()) {\\r\\n            throw new CommonException(\\\"您没有权限编辑竞赛报名关联\\\");\\r\\n        }\\r\\n        if(ObjectUtil.isNotEmpty(loginUserDataScope)) {\\r\\n            // 根据业务需要，取消下面注释并修改为实际的数据范围字段，例如：orgId\\r\\n            // if(!loginUserDataScope.contains(bizCompetitionProject.getOrgId())) {\\r\\n            //     throw new CommonException(\\\"您没有权限编辑该机构下的竞赛报名关联\\\");\\r\\n            // }\\r\\n        }\\r\\n\\r\\n        this.updateById(bizCompetitionProject);\\r\\n    }\\r\\n\\r\\n    @Transactional(rollbackFor = Exception.class)\\r\\n    @Override\\r\\n    public void delete(List<BizCompetitionProjectIdParam> bizCompetitionProjectIdParamList) {\\r\\n        // 校验数据范围\\r\\n        List<String> loginUserDataScope = StpLoginUserUtil.getLoginUserDataScope();\\r\\n        if(loginUserDataScope != null && loginUserDataScope.isEmpty()) {\\r\\n            throw new CommonException(\\\"您没有权限删除竞赛报名关联\\\");\\r\\n        }\\r\\n        if(ObjectUtil.isNotEmpty(loginUserDataScope)) {\\r\\n            // 根据业务需要，取消下面注释并修改为实际的数据范围字段，例如对删除的记录进行数据范围校验\\r\\n            // Set<String> orgIdSet = this.listByIds(CollStreamUtil.toList(bizCompetitionProjectIdParamList, BizCompetitionProjectIdParam::getId))\\r\\n            //         .stream().map(BizCompetitionProject::getOrgId).collect(Collectors.toSet());\\r\\n            // if(!new HashSet<>(loginUserDataScope).containsAll(orgIdSet)) {\\r\\n            //     throw new CommonException(\\\"您没有权限删除这些机构下的竞赛报名关联\\\");\\r\\n            // }\\r\\n        }\\r\\n        // 执行删除\\r\\n        this.removeByIds(CollStreamUtil.toList(bizCompetitionProjectIdParamList, BizCompetitionProjectIdParam::getId));\\r\\n    }\\r\\n\\r\\n    @Override\\r\\n    public BizCompetitionProject detail(BizCompetitionProjectIdParam bizCompetitionProjectIdParam) {\\r\\n        return this.queryEntity(bizCompetitionProjectIdParam.getId());\\r\\n    }\\r\\n\\r\\n    @Override\\r\\n    public BizCompetitionProject queryEntity(Serializable id) {\\r\\n        BizCompetitionProject bizCompetitionProject = this.getById(id);\\r\\n        if(ObjectUtil.isEmpty(bizCompetitionProject)) {\\r\\n            throw new CommonException(\\\"竞赛报名关联不存在，id值为：{}\\\", id);\\r\\n        }\\r\\n        return bizCompetitionProject;\\r\\n    }\\r\\n\\r\\n    @Override\\r\\n    public void downloadImportTemplate(HttpServletResponse response) throws IOException {\\r\\n       File tempFile = null;\\r\\n       try {\\r\\n         List<BizCompetitionProjectEditParam> dataList = CollectionUtil.newArrayList();\\r\\n         String fileName = \\\"竞赛报名关联导入模板_\\\" + DateUtil.format(DateTime.now(), DatePattern.PURE_DATETIME_PATTERN) + \\\".xlsx\\\";\\r\\n         tempFile = FileUtil.file(FileUtil.getTmpDir() + FileUtil.FILE_SEPARATOR + fileName);\\r\\n         EasyExcel.write(tempFile.getPath(), BizCompetitionProjectEditParam.class).sheet(\\\"竞赛报名关联\\\").doWrite(dataList);\\r\\n         CommonDownloadUtil.download(tempFile, response);\\r\\n       } catch (Exception e) {\\r\\n         log.error(\\\">>> 竞赛报名关联导入模板下载失败：\\\", e);\\r\\n         CommonResponseUtil.renderError(response, \\\"竞赛报名关联导入模板下载失败\\\");\\r\\n       } finally {\\r\\n         FileUtil.del(tempFile);\\r\\n       }\\r\\n    }\\r\\n\\r\\n    @Transactional(rollbackFor = Exception.class)\\r\\n    @Override\\r\\n    public JSONObject importData(MultipartFile file) {\\r\\n        try {\\r\\n            int successCount = 0;\\r\\n            int errorCount = 0;\\r\\n            JSONArray errorDetail = JSONUtil.createArray();\\r\\n            // 创建临时文件\\r\\n            File tempFile = FileUtil.writeBytes(file.getBytes(), FileUtil.file(FileUtil.getTmpDir() +\\r\\n                    FileUtil.FILE_SEPARATOR + \\\"bizCompetitionProjectImportTemplate.xlsx\\\"));\\r\\n            // 读取excel\\r\\n            List<BizCompetitionProjectEditParam> bizCompetitionProjectEditParamList =  EasyExcel.read(tempFile).head(BizCompetitionProjectEditParam.class).sheet()\\r\\n                    .headRowNumber(1).doReadSync();\\r\\n            List<BizCompetitionProject> allDataList = this.list();\\r\\n            for (int i = 0; i < bizCompetitionProjectEditParamList.size(); i++) {\\r\\n                JSONObject jsonObject = this.doImport(allDataList, bizCompetitionProjectEditParamList.get(i), i);\\r\\n                if(jsonObject.getBool(\\\"success\\\")) {\\r\\n                    successCount += 1;\\r\\n                } else {\\r\\n                    errorCount += 1;\\r\\n                    errorDetail.add(jsonObject);\\r\\n                }\\r\\n            }\\r\\n            return JSONUtil.createObj()\\r\\n                    .set(\\\"totalCount\\\", bizCompetitionProjectEditParamList.size())\\r\\n                    .set(\\\"successCount\\\", successCount)\\r\\n                    .set(\\\"errorCount\\\", errorCount)\\r\\n                    .set(\\\"errorDetail\\\", errorDetail);\\r\\n        } catch (Exception e) {\\r\\n            log.error(\\\">>> 竞赛报名关联导入失败：\\\", e);\\r\\n            throw new CommonException(\\\"竞赛报名关联导入失败\\\");\\r\\n        }\\r\\n    }\\r\\n\\r\\n    public JSONObject doImport(List<BizCompetitionProject> allDataList, BizCompetitionProjectEditParam bizCompetitionProjectEditParam, int i) {\\r\\n        String id = bizCompetitionProjectEditParam.getId();\\r\\n        if(ObjectUtil.hasEmpty(id)) {\\r\\n            return JSONUtil.createObj().set(\\\"index\\\", i + 1).set(\\\"success\\\", false).set(\\\"msg\\\", \\\"必填字段存在空值\\\");\\r\\n        } else {\\r\\n            try {\\r\\n                int index = CollStreamUtil.toList(allDataList, BizCompetitionProject::getId).indexOf(bizCompetitionProjectEditParam.getId());\\r\\n                BizCompetitionProject bizCompetitionProject;\\r\\n                boolean isAdd = false;\\r\\n                if(index == -1) {\\r\\n                    isAdd = true;\\r\\n                    bizCompetitionProject = new BizCompetitionProject();\\r\\n                } else {\\r\\n                    bizCompetitionProject = allDataList.get(index);\\r\\n                }\\r\\n                BeanUtil.copyProperties(bizCompetitionProjectEditParam, bizCompetitionProject);\\r\\n                if(isAdd) {\\r\\n                    allDataList.add(bizCompetitionProject);\\r\\n                } else {\\r\\n                    allDataList.remove(index);\\r\\n                    allDataList.add(index, bizCompetitionProject);\\r\\n                }\\r\\n                this.saveOrUpdate(bizCompetitionProject);\\r\\n                return JSONUtil.createObj().set(\\\"success\\\", true);\\r\\n            } catch (Exception e) {\\r\\n              log.error(\\\">>> 数据导入异常：\\\", e);\\r\\n              return JSONUtil.createObj().set(\\\"success\\\", false).set(\\\"index\\\", i + 1).set(\\\"msg\\\", \\\"数据导入异常\\\");\\r\\n            }\\r\\n        }\\r\\n    }\\r\\n\\r\\n    @Override\\r\\n    public void exportData(List<BizCompetitionProjectIdParam> bizCompetitionProjectIdParamList, HttpServletResponse response) throws IOException {\\r\\n       File tempFile = null;\\r\\n       try {\\r\\n         List<BizCompetitionProjectEditParam> dataList;\\r\\n         if(ObjectUtil.isNotEmpty(bizCompetitionProjectIdParamList)) {\\r\\n            List<Serializable> idList = CollStreamUtil.toList(bizCompetitionProjectIdParamList, BizCompetitionProjectIdParam::getId);\\r\\n            dataList = BeanUtil.copyToList(this.listByIds(idList), BizCompetitionProjectEditParam.class);\\r\\n         } else {\\r\\n            dataList = BeanUtil.copyToList(this.list(), BizCompetitionProjectEditParam.class);\\r\\n         }\\r\\n         String fileName = \\\"竞赛报名关联_\\\" + DateUtil.format(DateTime.now(), DatePattern.PURE_DATETIME_PATTERN) + \\\".xlsx\\\";\\r\\n         tempFile = FileUtil.file(FileUtil.getTmpDir() + FileUtil.FILE_SEPARATOR + fileName);\\r\\n         EasyExcel.write(tempFile.getPath(), BizCompetitionProjectEditParam.class).sheet(\\\"竞赛报名关联\\\").doWrite(dataList);\\r\\n         CommonDownloadUtil.download(tempFile, response);\\r\\n       } catch (Exception e) {\\r\\n         log.error(\\\">>> 竞赛报名关联导出失败：\\\", e);\\r\\n         CommonResponseUtil.renderError(response, \\\"竞赛报名关联导出失败\\\");\\r\\n       } finally {\\r\\n         FileUtil.del(tempFile);\\r\\n       }\\r\\n    }\\r\\n}\\r\\n\"}]},\"traceId\":\"ae307e2fe1d14164bef77dcabe8ec8e6\"}','2026-10-04 13:31:53','超管','3044022100d1497fc4fbfa6e4b59d93dfa961219ba69044a991d0ea2c1f3e803f7e8653e3e021f3f0c47b5dd9c0ad358840603362da57faa3cba2248e2f2d2401d6379f26927','2026-10-04 13:31:53','-1',NULL,NULL),('2106618289296519169','OPERATE','添加代码生成基础','SUCCESS',NULL,'127.0.0.1','内网IP|内网IP','axios/1.7.7','-','vip.xiaonuo.gen.modular.basic.controller.GenBasicController','add','/gen/basic/add','/gen/basic/add','{\"genBasicAddParam\":\"{\\\"dbTable\\\":\\\"biz_competition_certificate\