\\t\\tonClose()\\r\\n\\t\\t\\t\\t\\t\\temit(\'successful\')\\r\\n\\t\\t\\t\\t\\t})\\r\\n\\t\\t\\t\\t\\t.finally(() => {\\r\\n\\t\\t\\t\\t\\t\\tsubmitLoading.value = false\\r\\n\\t\\t\\t\\t\\t})\\r\\n\\t\\t\\t})\\r\\n\\t\\t\\t.catch(() => {})\\r\\n\\t}\\r\\n\\t// 抛出函数\\r\\n\\tdefineExpose({\\r\\n\\t\\tonOpen\\r\\n\\t})\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"detail.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\follow\\\\detail.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container\\r\\n\\t\\ttitle=\\\"详情\\\"\\r\\n\\t\\t:width=\\\"700\\\"\\r\\n\\t\\tv-model:open=\\\"open\\\"\\r\\n\\t\\t:destroy-on-close=\\\"true\\\"\\r\\n\\t\\t@close=\\\"onClose\\\"\\r\\n\\t>\\r\\n\\t\\t<a-descriptions :column=\\\"1\\\" bordered size=\\\"small\\\">\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"关注人学生用户ID（关联SYS_USER.ID）\\\">\\r\\n\\t\\t\\t\\t{{ formData.userId }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"关注目标类型：COMPETITION-竞赛, PROJECT-项目组\\\">\\r\\n\\t\\t\\t\\t{{ formData.targetType }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"目标ID（根据TARGET_TYPE关联BIZ_COMPETITION.ID或BIZ_PROJECT.ID）\\\">\\r\\n\\t\\t\\t\\t{{ formData.targetId }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"关注时间\\\">\\r\\n\\t\\t\\t\\t{{ formData.followTime }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"删除标志\\\">\\r\\n\\t\\t\\t\\t{{ formData.deleteFlag }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"创建时间\\\">\\r\\n\\t\\t\\t\\t{{ formData.createTime }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"创建用户\\\">\\r\\n\\t\\t\\t\\t{{ formData.createUser }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"修改时间\\\">\\r\\n\\t\\t\\t\\t{{ formData.updateTime }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"修改用户\\\">\\r\\n\\t\\t\\t\\t{{ formData.updateUser }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"排序码\\\">\\r\\n\\t\\t\\t\\t{{ formData.sortCode }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t</a-descriptions>\\r\\n\\t</xn-form-container>\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"bizFollowDetail\\\">\\r\\n\\timport { cloneDeep } from \'lodash-es\'\\r\\n\\timport bizFollowApi from \'@/api/biz/bizFollowApi\'\\r\\n\\r\\n\\t// 抽屉状态\\r\\n\\tconst open = ref(false)\\r\\n\\t// 表单数据\\r\\n\\tconst formData = ref({})\\r\\n\\r\\n\\t// 打开抽屉\\r\\n\\tconst onOpen = (record) => {\\r\\n\\t\\topen.value = true\\r\\n\\t\\tbizFollowApi.bizFollowDetail({ id: record.id }).then((data) => {\\r\\n\\t\\t\\tformData.value = data\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 关闭抽屉\\r\\n\\tconst onClose = () => {\\r\\n\\t\\tformData.value = {}\\r\\n\\t\\topen.value = false\\r\\n\\t}\\r\\n\\t// 下载文件\\r\\n\\tconst downloadFile = (url) => {\\r\\n\\t\\twindow.open(url)\\r\\n\\t}\\r\\n\\t// 抛出函数\\r\\n\\tdefineExpose({\\r\\n\\t\\tonOpen\\r\\n\\t})\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"index.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\follow\\\\index.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-panel>\\r\\n\\t\\t<s-table\\r\\n\\t\\t\\tref=\\\"tableRef\\\"\\r\\n\\t\\t\\t:columns=\\\"columns\\\"\\r\\n\\t\\t\\t:data=\\\"loadData\\\"\\r\\n\\t\\t\\t:alert=\\\"options.alert.show\\\"\\r\\n\\t\\t\\tbordered\\r\\n\\t\\t\\t:row-key=\\\"(record) => record.id\\\"\\r\\n\\t\\t\\t:tool-config=\\\"toolConfig\\\"\\r\\n\\t\\t\\t:row-selection=\\\"options.rowSelection\\\"\\r\\n\\t\\t\\t:scroll=\\\"{ x: \'max-content\' }\\\"\\r\\n\\t\\t>\\r\\n\\t\\t\\t<template #operator>\\r\\n\\t\\t\\t\\t<a-space>\\r\\n\\t\\t\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"formRef.onOpen()\\\" v-if=\\\"hasPerm(\'bizFollowAdd\')\\\">\\r\\n\\t\\t\\t\\t\\t\\t<template #icon><plus-outlined /></template>\\r\\n\\t\\t\\t\\t\\t\\t新增\\r\\n\\t\\t\\t\\t\\t</a-button>\\r\\n\\t\\t\\t\\t\\t<a-button @click=\\\"impor