\\n\\t// 列表选择配置\\r\\n\\tconst options = {\\r\\n\\t\\talert: {\\r\\n\\t\\t\\tshow: true,\\r\\n\\t\\t\\tclear: () => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\r\\n\\t\\t\\t}\\r\\n\\t\\t},\\r\\n\\t\\trowSelection: {\\r\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\r\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\r\\n\\t\\t\\t}\\r\\n\\t\\t}\\r\\n\\t}\\r\\n\\tconst loadData = (parameter) => {\\r\\n\\t\\treturn bizProjectRecruitApi.bizProjectRecruitPage(parameter).then((data) => {\\r\\n\\t\\t\\treturn data\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 重置\\r\\n\\tconst reset = () => {\\r\\n\\t\\tsearchFormRef.value.resetFields()\\r\\n\\t\\ttableRef.value.refresh(true)\\r\\n\\t}\\r\\n\\t// 删除\\r\\n\\tconst deleteBizProjectRecruit = (record) => {\\r\\n\\t\\tlet params = [\\r\\n\\t\\t\\t{\\r\\n\\t\\t\\t\\tid: record.id\\r\\n\\t\\t\\t}\\r\\n\\t\\t]\\r\\n\\t\\tbizProjectRecruitApi.bizProjectRecruitDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.refresh(true)\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 导出\\r\\n    const exportData = () => {\\r\\n        if (selectedRowKeys.value.length > 0) {\\r\\n            const params = selectedRowKeys.value.map((m) => {\\r\\n                return {\\r\\n                    id: m\\r\\n                }\\r\\n            })\\r\\n            bizProjectRecruitApi.bizProjectRecruitExport(params).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        } else {\\r\\n            bizProjectRecruitApi.bizProjectRecruitExport([]).then((res) => {\\r\\n                downloadUtil.resultDownload(res)\\r\\n            })\\r\\n        }\\r\\n    }\\r\\n\\t// 批量删除\\r\\n\\tconst deleteBatchBizProjectRecruit = (params) => {\\r\\n\\t\\tbizProjectRecruitApi.bizProjectRecruitDelete(params).then(() => {\\r\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\r\\n\\t\\t})\\r\\n\\t}\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\projectrecruit\\\\importModel.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\r\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\r\\n\\t\\t</span>\\r\\n\\t\\t<a-divider dashed />\\r\\n\\t\\t<div>\\r\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\r\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\r\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\r\\n\\t\\t\\t\\t\\t</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-text\\\">单击或拖动文件到此区域进行上传</p>\\r\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-hint\\\">仅支持xls、xlsx格式文件</p>\\r\\n\\t\\t\\t\\t</a-upload-dragger>\\r\\n\\t\\t\\t</a-spin>\\r\\n\\t\\t</div>\\r\\n\\t\\t<a-alert v-if=\\\"impAlertStatus\\\" type=\\\"info\\\" :show-icon=\\\"false\\\" banner closable @close=\\\"onImpClose\\\" class=\\\"mt-3\\\">\\r\\n\\t\\t\\t<template #description>\\r\\n\\t\\t\\t\\t<p>导入总数：{{ impResultData.totalCount }} 条</p>\\r\\n\\t\\t\\t\\t<p>导入成功：{{ impResultData.successCount }} 条</p>\\r\\n\\t\\t\\t\\t<div v-if=\\\"impResultData.errorCount > 0\\\">\\r\\n\\t\\t\\t\\t\\t<p><span class=\\\"xn-color-red\\\">失败条数：</span>{{ impResultData.errorCount }} 条</p>\\r\\n\\t\\t\\t\\t\\t<a-table :dataSource=\\\"impResultErrorDataSource\\\" :columns=\\\"impErrorColumns\\\" size=\\\"small\\\" />\\r\\n\\t\\t\\t\\t</div>\\r\\n\\t\\t\\t</template>\\r\\n\\t\\t</a-alert>\\r\\n\\t</xn-form-container>\\r\\n</template>\\r\\n\\r\\n<script setup name=\\\"bizProjectRecruitImportModel\\\">\\r\\n\\timport { message } from \'ant-design-vue\'\\r\\n\\timport bizProjectRecruitApi from \'@/api/biz/bizProjectRecruitApi\'\\r\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\r\\n\\r\\n\\tconst impUploadLoading = ref(false)\\r\\n\\tconst impAlertStatus = ref(false)\\r\\n\\tconst impResultData = ref({})\\r\\n\\tconst impResultErrorDataSource = ref([])\\r\\n\\tconst impAccept = [\\r\\n\\t\\t{\\r\\n\\t\\t\\textension: \'.xls\',\\r\\n\\t\\t\\tmimeType: \'application/vnd.ms-excel\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\textension: \'.xlsx\',\\r\\n\\t\\t\\tmimeType: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\'\\r\\n\\t\\t}\\r\\n\\t]\\r\\n\\t// 指定能选择的文件类型\\r\\n\\tconst uploadAccept = String(\\r\\n\\t\\timpAccept.map((item) => {\\r\\n\\t\\t\\treturn item.mimeType\\r\\n\\t\\t})\\r\\n\\t)\\r\\n\\t// 导入\\r\\n\\tconst customRequestLocal = (data) => {\\r\\n\\t\\timpUploadLoading.value = true\\r\\n\\t\\tconst fileData = new FormData()\\r\\n\\t\\t// 校验上传文件扩展名和文件类型是否为.xls、.xlsx\\r\\n\\t\\tconst extension = \'.\'.concat(data.file.name.split(\'.\').slice(-1).toString().toLowerCase())\\r\\n\\t\\tconst mimeType = data.file.type\\r\\n\\t\\t// 提取允许的扩展名\\r\\n\\t\\tconst extensionArr = impAccept.map((item) => item.extension)\\r\\n\\t\\t// 提取允许的MIMEType\\r\\n\\t\\tconst mimeTypeArr = impAccept.map((item) => item.mimeType)\\r\\n\\t\\tif (!extensionArr.includes(extension) || !mimeTypeArr.includes(mimeType)) {\\r\\n\\t\\t\\tmessage.warning(\'上传文件类型仅支持xls、xlsx格式文件！\')\\r\\n\\t\\t\\timpUploadLoading.value = false\\r\\n\\t\\t\\treturn false\\r\\n\\t\\t}\\r\\n\\t\\tfileData.append(\'file\', data.file)\\r\\n\\t\\treturn bizProjectRecruitApi\\r\\n\\t\\t\\t.bizProjectRecruitImport(fileData)\\r\\n\\t\\t\\t.then((res) => {\\r\\n\\t\\t\\t\\timpAlertStatus.value = true\\r\\n\\t\\t\\t\\timpResultData.value = res\\r\\n\\t\\t\\t\\timpResultErrorDataSource.value = res.errorDetail\\r\\n\\t\\t\\t})\\r\\n\\t\\t\\t.finally(() => {\\r\\n\\t\\t\\t\\timpUploadLoading.value = false\\r\\n\\t\\t\\t})\\r\\n\\t}\\r\\n\\t// 关闭导入提示\\r\\n\\tconst onImpClose = () => {\\r\\n\\t\\timpAlertStatus.value = false\\r\\n\\t}\\r\\n\\tconst impErrorColumns = [\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'索引\',\\r\\n\\t\\t\\tdataIndex: \'index\',\\r\\n\\t\\t\\twidth: \'80px\'\\r\\n\\t\\t},\\r\\n\\t\\t{\\r\\n\\t\\t\\ttitle: \'原因\',\\r\\n\\t\\t\\tdataIndex: \'msg\'\\r\\n\\t\\t}\\r\\n\\t]\\r\\n\\t// 定义emit事件\\r\\n\\tconst emit = defineEmits({ successful: null })\\r\\n\\t// 默认是关闭状态\\r\\n\\tconst visible = ref(false)\\r\\n\\tconst submitLoading = ref(false)\\r\\n\\r\\n\\t// 打开抽屉\\r\\n\\tconst onOpen = () => {\\r\\n\\t\\tvisible.value = true\\r\\n\\t}\\r\\n\\t// 关闭抽屉\\r\\n\\tconst onClose = () => {\\r\\n\\t\\tvisible.value = false\\r\\n\\t\\t// 关闭导入的提示\\r\\n\\t\\tonImpClose()\\r\\n\\t}\\r\\n\\t// 下载导入模板\\r\\n\\tconst downloadImportTemplate = () => {\\r\\n\\t\\tbizProjectRecruitApi.bizProjectRecruitDownloadTemplate().then((res) => {\\r\\n\\t\\t\\tdownloadUtil.resultDownload(res)\\r\\n\\t\\t})\\r\\n\\t}\\r\\n\\t// 调用这个函数将子组件的一些数据和方法暴露出去\\r\\n\\tdefineExpose({\\r\\n\\t\\tonOpen\\r\\n\\t})\\r\\n</script>\\r\\n<style scoped>\\r\\n\\t.xn-color-red {\\r\\n\\t\\tcolor: #ff0000;\\r\\n\\t}\\r\\n</style>\\r\\n\"}],\"genBasicCodeBackendResultList\":[{\"codeFileName\":\"BizProjectRecruitController.java\",\"codeFileWithPathName\":\"vip\\\\xiaonuo\\\\biz\\\\modular\\\\projectrecruit\\\\controller\\\\BizProjectRecruitController.java\",\"codeFileContent\":\"/*\\r\\n * Copyright [2022] [https://www.xiaonuo.vip]\\r\\n *\\r\\n * Snowy采用APACHE LICENSE 2.0开源协议，您在使用过程中，需要注意以下几点：\\r\\n *\\r\\n * 1.请不要删除和修改根目录下的LICENSE文件。\\r\\n * 2.请不要删除和修改Snowy源码头部的版权声明。\\r\\n * 3.本项目代码可免费商业使用，商业使用请保留源码和相关描述文件的项目出处，作者声明等。\\r\\n * 4.分发源码时候，请注明软件出处 https://www.xiaonuo.vip\\r\\n * 5.不可二次分发开源参与同类竞品，如有想法可联系团队xiaonuobase@qq.com商议合作。\\r\\n * 6.若您的项目无法满足以上几点，需要更多功能代码，获取Snowy商业授权许可，请在官网购买授权，地址为 https://www.xiaonuo.vip\\r\\n */\\r\\npackage vip.xiaonuo.biz.modular.projectrecruit.controller;\\r\\n\\r\\nimport cn.dev33.satoken.annotation.SaCheckPermission;\\r\\nimport cn.hutool.json.JSONObject;\\r\\nimport com.baomidou.mybatisplus.extension.plugins.pagination.Page;\\r\\nimport io.swagger.v3.oas.annotations.tags.Tag;\\r\\nimport io.swagger.v3.oas.annotations.Operation;\\r\\nimport jakarta.servlet.http.HttpServletResponse;\\r\\nimport org.springframework.http.MediaType;\\r\\nimport org.springframework.validation.annotation.Validated;\\r\\nimport org.springframework.web.bind.annotation.*;\\r\\nimport org.springframework.web.multipart.MultipartFile;\\r\\nimport vip.xiaonuo.common.annotation.CommonLog;\\r\\nimport vip.xiaonuo.common.pojo.CommonResult;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.entity.BizProjectRecruit;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.param.BizProjectRecruitAddParam;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.param.BizProjectRecruitEditParam;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.param.BizProjectRecruitIdParam;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.param.BizProjectRecruitPageParam;\\r\\nimport vip.xiaonuo.biz.modular.projectrecruit.service.BizProjectRecruitService;\\r\\n\\r\\nimport jakarta.annotation.Resource;\\r\\nimport jakarta.validation.Valid;\\r\\nimport jakarta.validation.constraints.NotEmpty;\\r\\nimport java.io.IOException;\\r\\nimport java.util.List;\\r\\n\\r\\n/**\\r\\n * 项目招募需求控制器\\r\\n *\\r\\n * @author antigravity\\r\\n * @date  2026/10/04 13:31\\r\\n */\\r\\n@Tag(name = \\\"项目招募需求控制器\\\")\\r\\n@RestController\\r\\n@Validated\\r\\npublic class BizProjectRecruitController {\\r\\n\\r\\n    @Resource\\r\\n    private BizProjectRecruitService bizProjectRecruitService;\\r\\n\\r\\n    /**\\r\\n     * 获取项目招募需求分页\\r\\n     *\\r\\n     * @author antigravity\\r\\n     * @date  2026/10/04 13:31\\r\\n     */\\r\\n    @Operation(summary = \\\"获取项目招募需求分页\\\")\\r\\n    @SaCheckPermission(\\\"/biz/projectrecruit/page\\\")\\r\\n    @GetMapping(\\\"/biz/projectrecruit/page\\\")\\r\\n    public CommonResult<Page<BizProjectRecruit>> page(BizProjectRecruitPageParam bizProjectRecruitPageParam) {\\r\\n        return CommonResult.data(bizProjectRecruitService.page(bizProjectRecruitPageParam));\\r\\n    }\\r\\n\\r\\n    /**\\r\\n     * 添加项