t\\t\\t\\t\\t.bizAiEvaluationSubmitForm(formDataParam, formDataParam.id)\\r\\n\\t\\t\\t\\t\\t.then(() => {\\r\\n\\t\\t\\t\\t\\t\\tonClose()\\r\\n\\t\\t\\t\\t\\t\\temit(\'successful\')\\r\\n\\t\\t\\t\\t\\t})\\r\\n\\t\\t\\t\\t\\t.finally(() => {\\r\\n\\t\\t\\t\\t\\t\\tsubmitLoading.value = false\\r\\n\\t\\t\\t\\t\\t})\\r\\n\\t\\t\\t})\\r\\n\\t\\t\\t.catch(() => {})\\r\\n\\t}\\r\\n\\t// 抛出函数\\r\\n\\tdefineExpose({\\r\\n\\t\\tonOpen\\r\\n\\t})\\r\\n</script>\\r\\n\"},{\"codeFileName\":\"detail.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\aievaluation\\\\detail.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container\\r\\n\\t\\ttitle=\\\"详情\\\"\\r\\n\\t\\t:width=\\\"700\\\"\\r\\n\\t\\tv-model:open=\\\"open\\\"\\r\\n\\t\\t:destroy-on-close=\\\"true\\\"\\r\\n\\t\\t@close=\\\"onClose\\\"\\r\\n\\t>\\r\\n\\t\\t<a-descriptions :column=\\\"1\\\" bordered size=\\\"small\\\">\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"评估的项目组ID（关联BIZ_PROJECT.ID）\\\">\\r\\n\\t\\t\\t\\t{{ formData.projectId }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"触发评估人用户ID（组长或老师，关联SYS_USER.ID）\\\">\\r\\n\\t\\t\\t\\t{{ formData.triggerUserId }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"评估批次/周期（如 2026-Q1, STAGE_1 等）\\\">\\r\\n\\t\\t\\t\\t{{ formData.evaluationBatch }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"组员算法整体完成度百分比(0-100)\\\">\\r\\n\\t\\t\\t\\t{{ formData.algorithmCompletionRate }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"竞赛参与度与活跃度得分(0-100)\\\">\\r\\n\\t\\t\\t\\t{{ formData.competitionParticipationScore }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"AI加权综合评估得分(0-100)\\\">\\r\\n\\t\\t\\t\\t{{ formData.aiTotalScore }}\\r\\n\\t\\t\\t</a-descriptions-item>\\r\\n\\t\\t\\t<a-descriptions-item label=\\\"AI生成的诊断报告文本（含各维度深度分析、优势分析、短板预警及提升建议）\\\">\\r\\n\\t\\t\\t\\t{{ formData.aiEvaluationReport }}\\r\\n\\t