  `QUERY_TYPE` varchar(255) DEFAULT NULL COMMENT '查询方式',
  `WHETHER_DETAIL` varchar(255) DEFAULT NULL COMMENT '详情显示',
  `TABLE_TYPE` varchar(20) DEFAULT 'MAIN' COMMENT '所属表类型：MAIN主表/SUB子表',
