DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_user` (
  `ID` varchar(20) NOT NULL COMMENT '主键',
  `AVATAR` longtext DEFAULT NULL COMMENT '头像',
  `SIGNATURE` longtext DEFAULT NULL COMMENT '签名',
  `ACCOUNT` varchar(255) DEFAULT NULL COMMENT '账号',
  `PASSWORD` varchar(255) DEFAULT NULL COMMENT '密码',
  `NAME` varchar(255) DEFAULT NULL COMMENT '姓名',
  `NICKNAME` varchar(255) DEFAULT NULL COMMENT '昵称',
  `GENDER` varchar(255) DEFAULT NULL COMMENT '性别',
  `AGE` varchar(255) DEFAULT NULL COMMENT '年龄',
  `BIRTHDAY` varchar(255) DEFAULT NULL COMMENT '出生日期',
  `NATION` varchar(255) DEFAULT NULL COMMENT '民族',
  `NATIVE_PLACE` varchar(255) DEFAULT NULL COMMENT '籍贯',
  `HOME_ADDRESS` text DEFAULT NULL COMMENT '家庭住址',
  `MAILING_ADDRESS` text DEFAULT NULL COMMENT '通信地址',
  `ID_CARD_TYPE` varchar(255) DEFAULT NULL COMMENT '证件类型',
  `ID_CARD_NUMBER` varchar(255) DEFAULT NULL COMMENT '证件号码',
  `CULTURE_LEVEL` varchar(255) DEFAULT NULL COMMENT '文化程度',
  `POLITICAL_OUTLOOK` varchar(255) DEFAULT NULL COMMENT '政治面貌',
  `COLLEGE` varchar(255) DEFAULT NULL COMMENT '毕业院校',
  `EDUCATION` varchar(255) DEFAULT NULL COMMENT '学历',
  `EDU_LENGTH` varchar(255) DEFAULT NULL COMMENT '学制',
  `DEGREE` varchar(255) DEFAULT NULL COMMENT '学位',
  `PHONE` varchar(255) DEFAULT NULL COMMENT '手机',
  `EMAIL` varchar(255) DEFAULT NULL COMMENT '邮箱',
  `HOME_TEL` varchar(255) DEFAULT NULL COMMENT '家庭电话',
  `OFFICE_TEL` varchar(255) DEFAULT NULL COMMENT '办公电话',
  `EMERGENCY_CONTACT` varchar(255) DEFAULT NULL COMMENT '紧急联系人',
  `EMERGENCY_PHONE` varchar(255) DEFAULT NULL COMMENT '紧急联系人电话',
  `EMERGENCY_ADDRESS` text DEFAULT NULL COMMENT '紧急联系人地址',
  `EMP_NO` varchar(255) DEFAULT NULL COMMENT '员工编号',
  `ENTRY_DATE` varchar(255) DEFAULT NULL COMMENT '入职日期',
  `ORG_ID` varchar(20) DEFAULT NULL COMMENT '机构id',
  `POSITION_ID` varchar(20) DEFAULT NULL COMMENT '职位id',
  `POSITION_LEVEL` varchar(255) DEFAULT NULL COMMENT '职级',
  `DIRECTOR_ID` varchar(20) DEFAULT NULL COMMENT '主管id',
  `POSITION_JSON` longtext DEFAULT NULL COMMENT '兼任信息',
  `LAST_LOGIN_IP` varchar(255) DEFAULT NULL COMMENT '上次登录ip',
  `LAST_LOGIN_ADDRESS` varchar(255) DEFAULT NULL COMMENT '上次登录地点',
  `LAST_LOGIN_TIME` datetime DEFAULT NULL COMMENT '上次登录时间',
  `LAST_LOGIN_DEVICE` text DEFAULT NULL COMMENT '上次登录设备',
  `LATEST_LOGIN_IP` varchar(255) DEFAULT NULL COMMENT '最新登录ip',
  `LATEST_LOGIN_ADDRESS` varchar(255) DEFAULT NULL COMMENT '最新登录地点',
  `LATEST_LOGIN_TIME` datetime DEFAULT NULL COMMENT '最新登录时间',
  `LATEST_LOGIN_DEVICE` text DEFAULT NULL COMMENT '最新登录设备',
  `USER_STATUS` varchar(255) DEFAULT NULL COMMENT '用户状态',
  `SORT_CODE` int(11) DEFAULT NULL COMMENT '排序码',
  `EXT_JSON` longtext DEFAULT NULL COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='用户';
